def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Full uniform lines in the non-background separator color.
    row_cuts = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_cuts = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def segments(n, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, n))
        return result

    rows = segments(h, row_cuts)
    cols = segments(w, col_cuts)

    # Use the compartment containing the most non-background cells as the motif.
    best = None
    for r0, r1 in rows:
        for c0, c1 in cols:
            pts = [(r-r0, c-c0, grid[r][c])
                   for r in range(r0, r1)
                   for c in range(c0, c1)
                   if grid[r][c] != bg]
            if best is None or len(pts) > len(best[2]):
                best = (r1-r0, c1-c0, pts)

    th, tw, motif = best
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            for dr, dc, color in motif:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = color
    return out
